204	    /** The late charge on a claim's figure now (see {@link #dueNow}); zero when it is not overdue. */
205	    private BigDecimal lateCharge(String sheetId, Claim claim, BigDecimal figure) {
206	        BigDecimal charge = BigDecimal.ZERO.setScale(2);
207	        if (!claim.open() || claim.deferred()) return charge;
208	        List<Date> found = jdbc.queryForList("SELECT today FROM sheet WHERE id = ?", Date.class, sheetId);
209	        if (found.isEmpty()) return charge;
210	        LocalDate today = found.get(0).toLocalDate();
211	        LocalDate dueBy = LocalDate.parse(claim.dueBy());
212	        long periods = dueBy.isBefore(today) ? ChronoUnit.DAYS.between(dueBy, today) / 30 : 0;
213	        if (periods == 0) return charge;
214	        RoundingMode rounding = rounding(sheetId, claim);
215	        for (long n = 1; n <= periods; n++) {
216	            BigDecimal pct = settings.latePct(sheetId, dueBy.plusDays(30 * n));
217	            if (pct == null || pct.signum() == 0) continue;
218	            charge = charge.add(figure.multiply(pct).movePointLeft(2).setScale(2, rounding));
219	        }
220	        return charge;
221	    }
