387	        return true;
388	    }
389	
390	    /** Release a claim's lock when {@code by} holds it. */
391	    public void unlock(String sheetId, long claimId, String by) {
392	        jdbc.update("UPDATE claim SET locked_by = NULL WHERE id = ? AND sheet_id = ? AND locked_by = ?", claimId, sheetId, by);
393	    }
394	
395	    /** Release every claim lock on the sheet (its today changed). */
396	    public void unlockAll(String sheetId) {
397	        jdbc.update("UPDATE claim SET locked_by = NULL WHERE sheet_id = ? AND locked_by IS NOT NULL", sheetId);
398	    }
399	
400	    /** Who holds a claim's lock; null when it is not locked. */
401	    public String lockedBy(String sheetId, long claimId) {
402	        List<String> found = jdbc.queryForList("SELECT locked_by FROM claim WHERE id = ? AND sheet_id = ?", String.class,
403	                claimId, sheetId);
404	        return found.isEmpty() ? null : found.get(0);
405	    }
406	
407	    /** Who holds each locked claim of the sheet, by claim id. */
408	    public Map<String, String> locks(String sheetId) {
409	        Map<String, String> locks = new LinkedHashMap<>();
410	        jdbc.query("SELECT id, locked_by FROM claim WHERE sheet_id = ? AND locked_by IS NOT NULL",
411	                rs -> {
412	                    locks.put(String.valueOf(rs.getLong("id")), rs.getString("locked_by"));
413	                }, sheetId);
414	        return locks;
415	    }
416	
417	    /** Write a line of a claim's status log: its status now, who moved it there, the sheet's today and its
418	     *  due as computed now. */
419	    public void log(String sheetId, long claimId, String by) {
420	        Claim claim = find(sheetId, claimId);
421	        if (claim == null) return;
422	        jdbc.update("INSERT INTO claim_log (sheet_id, claim_id, status, by_user, on_date, due)"
423	                + " SELECT ?, ?, ?, ?, today, ? FROM sheet WHERE id = ?",
424	                sheetId, claimId, claim.status(), by, dueNow(sheetId, claim), sheetId);
425	    }
426	
427	    /** How many days the sheet's today is past the date a claim's status log last records it SETTLED; null when
428	     *  it records no SETTLED line. */
429	    public Long daysSinceSettled(String sheetId, long claimId) {
430	        List<Long> found = jdbc.query("SELECT DATEDIFF('DAY', l.on_date, s.today) AS days FROM claim_log l"
431	                + " JOIN sheet s ON s.id = l.sheet_id WHERE l.sheet_id = ? AND l.claim_id = ? AND l.status = 'SETTLED'"
432	                + " ORDER BY l.id DESC LIMIT 1", (rs, i) -> rs.getLong("days"), sheetId, claimId);
433	        return found.isEmpty() ? null : found.get(0);
434	    }
435	
436	    /** The status logs of the sheet's claims, by claim id: each a line per status it has had, oldest first,
437	     *  as "<STATUS> by <user> on <date> due=<due>" ('n/a' when it had no due). */
438	    public Map<String, List<String>> logs(String sheetId) {
439	        Map<String, List<String>> logs = new LinkedHashMap<>();
440	        jdbc.query("SELECT claim_id, status, by_user, on_date, due FROM claim_log WHERE sheet_id = ? ORDER BY id",
441	                rs -> {
442	                    BigDecimal due = rs.getBigDecimal("due");
443	                    logs.computeIfAbsent(String.valueOf(rs.getLong("claim_id")), k -> new ArrayList<>())
444	                            .add(rs.getString("status") + " by " + rs.getString("by_user") + " on "
445	                                    + rs.getDate("on_date").toLocalDate() + " due=" + (due == null ? "n/a" : money(due)));
446	                }, sheetId);
447	        return logs;
448	    }
449	
450	    /** Each claim's status at the end of a day, by claim id, as its status log records it: the last line
451	     *  dated on or before it. A claim with no such line (added after that day) is absent. */
452	    public Map<Long, String> statusesOn(String sheetId, LocalDate day) {
453	        Map<Long, String> statuses = new LinkedHashMap<>();
454	        jdbc.query("SELECT claim_id, status FROM claim_log WHERE sheet_id = ? AND on_date <= ? ORDER BY id",
455	                rs -> {
456	                    statuses.put(rs.getLong("claim_id"), rs.getString("status"));
457	                }, sheetId, Date.valueOf(day));
458	        return statuses;
459	    }
460	
461	    /** An amount as shown: two decimals, a dot, no grouping. */
462	    static String money(BigDecimal amount) {
463	        return amount.setScale(2).toPlainString();
464	    }
465	
466	    /** A fixed due as shown, or null when there is none. */
467	    static String dueOf(BigDecimal due) {
468	        return due == null ? null : money(due);
469	    }
470	}
