import { PersonCells, PersonColumnHead } from '../../slots/defs/personRow';
import { claimsKey } from '../claims/useClaims';
import { peopleKey, usePeople, type Person } from '../people/usePeople';
import { usePersonRowAction } from '../people/usePersonRowAction';

/** A person's statements: how many have been taken, the last one's due-total and date (blank before
 *  the first), and a button that takes one. Taking a statement records their due-total and binds each
 *  of their counting claims to the figure it has then (unbinding the rest), until the next one; a
 *  steward can cancel the last one, its claims going live again. */
function PersonStatement({ sheetId, personId }: { sheetId: string; personId: number }) {
  const people = usePeople(sheetId);
  const queryClient = useQueryClient();
  const p = people.data?.find((x) => x.id === personId);

  const take = useMutation({
    mutationFn: () =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${personId}/statement`, {}),
    onSuccess: async () => {
      await Promise.all([
        queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) }),
        queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
      ]);
    },
  });
  const unstate = useMutation({
    mutationFn: () =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${personId}/unstate`, {}),
    onSuccess: async () => {
      await Promise.all([
        queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) }),
        queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
      ]);
    },
  });
  const { reset: resetTake } = take;
  const { reset: resetUnstate } = unstate;
  const reset = useCallback(() => {
    resetTake();
    resetUnstate();
  }, [resetTake, resetUnstate]);
  const announce = usePersonRowAction(sheetId, personId, reset);
  const error = take.error ?? unstate.error;

  return (
    <>
      <td data-testid="person-statement-count">{p?.statementCount ?? 0}</td>
      <td data-testid="person-stated-total">{p?.statedTotal ?? ''}</td>
      <td data-testid="person-statement-date">{p?.statementDate ?? ''}</td>
      <td>
        <button
          type="button"
          data-testid="person-statement"
          disabled={take.isPending}
          onClick={() => {
            announce();
            reset();
            take.mutate();
          }}
        >
          Statement
        </button>
        <button
          type="button"
          data-testid="person-unstate"
          disabled={unstate.isPending}
          onClick={() => {
            announce();
            reset();
            unstate.mutate();
          }}
        >
          Cancel statement
        </button>
        {error && <span data-testid="person-error">{error.message}</span>}
      </td>
    </>
  );
}

export const contributions = [
  PersonColumnHead.fill({
    order: 30,
    Component: () => (
      <>
        <th>Statements</th>
        <th>Stated total</th>
        <th>Stated on</th>
        <th />
      </>
    ),
  }),
  PersonCells.fill({ order: 30, Component: PersonStatement }),
];
import { useEffect, useId } from 'react';

// The actions on a person's row (statement, hold, retire) live in separate slots, but share the row's one
// `person-error`. Taking any of them announces it on the row, and every other action there clears its old
// error, so a refusal left by one action never shows beside (or for) the next.
const bus = new EventTarget();

/** Clear this action's error (`reset`) when another action on the same row is taken; returns the
 *  `announce` to call as this action is taken. */
export function usePersonRowAction(sheetId: string, personId: number, reset: () => void): () => void {
  const self = useId();
  const row = `${sheetId}/${personId}`;
  useEffect(() => {
    const listener = (e: Event) => {
      const d = (e as CustomEvent<{ row: string; from: string }>).detail;
      if (d.row === row && d.from !== self) reset();
    };
    bus.addEventListener('person-action', listener);
    return () => bus.removeEventListener('person-action', listener);
  }, [row, self, reset]);
  return () => bus.dispatchEvent(new CustomEvent('person-action', { detail: { row, from: self } }));
}
